package e.e.a;
import java.util.*;import java.lang.reflect.*;import org.json.*;import android.content.SharedPreferences;
public class SearchRangeTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{
 long from=SearchRange.day(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ssZ").parse("2026-10-11 19:00:00+0900").getTime()).getTimeInMillis(),to=from+6*86400000L;
 Map<String,Object> p=new HashMap<>();p.put("search_range_from",from);p.put("search_range_to",to);p.put("search_range_min",60);p.put("search_range_max",300);
 SearchRange.settings=(SharedPreferences)Proxy.newProxyInstance(SharedPreferences.class.getClassLoader(),new Class[]{SharedPreferences.class},(obj,m,a)->p.containsKey(a[0])?p.get(a[0]):a[1]);
 String url=SearchRange.url(new int[]{0,0,8,8},"test");SearchFilterRules.Query q=new SearchFilterRules.Query(url);check(q.getQueryParameter("minRegisteredAt").equals("2026-10-11T00:00:00+09:00"),"start of first Japanese day");check(q.getQueryParameter("maxRegisteredAt").equals("2026-10-17T23:59:59+09:00"),"end of inclusive last day");JSONObject video=new JSONObject().put("duration",60).put("registeredAt","2026-10-11T00:00:00+09:00");check(SearchFilterRules.matches(video,url),"lower inclusive bounds");video.put("duration",300).put("registeredAt","2026-10-17T23:59:59+09:00");check(SearchFilterRules.matches(video,url),"upper inclusive bounds");video.put("registeredAt","2026-10-18T00:00:00+09:00");check(!SearchFilterRules.matches(video,url),"next day excluded");video.put("registeredAt","2026-10-10T23:59:59+09:00");check(!SearchFilterRules.matches(video,url),"previous day excluded");video.put("registeredAt","2026-10-12T00:00:00+09:00").put("duration",59);check(!SearchFilterRules.matches(video,url),"lower duration excluded");video.put("duration",301);check(!SearchFilterRules.matches(video,url),"upper duration excluded");p.put("search_range_max",0);check(new SearchFilterRules.Query(SearchRange.url(new int[]{0,0,8,8},"test")).getQueryParameter("maxDuration")==null,"unlimited max");check(SearchRange.parse("10:05")==605&&SearchRange.time(605).equals("10:05"),"second precision");try{SearchRange.parse("1:60");throw new AssertionError("invalid seconds");}catch(IllegalArgumentException expected){}System.out.println("Custom date/duration ranges: 11 boundary checks passed");}
}
